/** Pin restored SQLite objects to schemas generated by the immutable app migrations. */
import { DatabaseSync } from 'node:sqlite';
import { migrate } from '../db/migrate';
import { migrations } from '../db/migrations';

/** Inspect before executing migrations or writes against an untrusted archive. */
export function validateRestoreSchema(path: string): void {
  const incoming = new DatabaseSync(path, { readOnly: true });
  const reference = new DatabaseSync(':memory:');
  try {
    incoming.exec('PRAGMA trusted_schema=OFF');
    const version = incoming.prepare('SELECT MAX(version) AS version FROM migrations').get()?.version;
    if (typeof version !== 'number' || !migrations.some(m => m.version === version)) throw new Error('storage.invalid_backup');
    migrate(reference, migrations.filter(m => m.version <= version));
    // SQLite creates statistics on optimize; their presence depends on query history.
    reference.exec('ANALYZE');
    const objects = (db: DatabaseSync) => db.prepare("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT IN ('sqlite_stat1','sqlite_stat4') ORDER BY type,name").all();
    if (JSON.stringify(objects(incoming)) !== JSON.stringify(objects(reference))) throw new Error('storage.invalid_backup');
    for (const name of ['sqlite_stat1', 'sqlite_stat4']) {
      const actual = incoming.prepare('SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name=?').get(name);
      if (actual && JSON.stringify(actual) !== JSON.stringify(reference.prepare('SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name=?').get(name))) throw new Error('storage.invalid_backup');
    }
  } finally { incoming.close(); reference.close(); }
}
